import { Link } from 'react-router-dom';
import { motion, useReducedMotion } from 'framer-motion';
import { FaArrowRight } from 'react-icons/fa';
import { personalInfo } from '../data/resumeData';

const Hero = () => {
  const reduceMotion = useReducedMotion();
  return (
    <section className="hero" aria-labelledby="intro-title">
      <p className="eyebrow">{personalInfo.title} <span aria-hidden="true">/</span> {personalInfo.location}</p>
      <h1 id="intro-title" className="hero-title">
        {['Thoughtful products.', 'Intelligent systems.'].map((line, index) => (
          <span className="hero-line" key={line}>
            <motion.span
              initial={reduceMotion ? false : { y: '105%' }}
              animate={{ y: 0 }}
              transition={{ duration: .7, delay: index * .08, ease: [.16, 1, .3, 1] }}
            >
              {index === 1 ? <em>{line}</em> : line}
            </motion.span>
          </span>
        ))}
      </h1>
      <div className="hero-bottom">
        <p className="hero-intro">
          I’m Athul, a {personalInfo.title} at <span className="text-primary">{personalInfo.company}</span>.
          My work spans product engineering, applied AI, and the systems that bring them into production.
        </p>
        <div className="hero-actions">
          <Link to="/projects" className="text-link">Explore my work <FaArrowRight aria-hidden="true" /></Link>
          <Link to="/contact" className="text-link quiet-link">Get in touch <span aria-hidden="true">↗</span></Link>
        </div>
      </div>
    </section>
  );
};

export default Hero;
